import os, glob, re

def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    block = ""
    for msg in t.split('\n'):
        sep = 'input' in msg and 'Demo pair' in msg
        if sep:
            # Read block
            lines = block.strip().split('\n')
            grid = []
            for row in lines:
                row_ints = [int(x) for x in row.split()]
                if row_ints:
                    grid.append(row_ints)
            if sep:
                G['input'] = grid if grid else G.get('input', grid)
                G['output'] = None
                current_key = 'input'
        elif 'output' in msg and 'pair' in msg:
            block = msg + '\n' + block
        elif not sep and block.strip():
            lines = block.strip().split('\n')
            grid = []
            for row in lines:
                row_ints = [int(x) for x in row.split()]
                if row_ints:
                    grid.append(row_ints)
            G[current_key] = grid if grid else G.get(current_key, grid)
            block = '\n' + msg + '\n' + block
            current_key = 'output'
        else:
            continue
    return G

